// 由 scripts/build-cafe-ts.py 從 docs/cafe-catalog.json 產出。改規格請改 manifest 再重跑，或直接手改本檔。
// 昭和喫茶版：footprint w×h＝佔地格（碰撞只認這個，h＝地面深度）；家具 sprite 自然比例往上長（overhang）。
import type { Facing, PlacedItem } from '../lib/shopstate.ts';

export type Z層 = 'rug' | 'furniture' | 'surface' | 'wall';

export interface CafeItem {
  id: string;
  category: string; // E6：目錄 UI 分頁籤 key（見 CATEGORY_LABELS）
  z: Z層;
  w: number; // 佔地寬（格）
  h: number; // 佔地深度（格，非視覺高度）
  name: string;
  sprite: string; // public 路徑（front）；其餘向由引擎按檔名慣例推導
  price: number;
  lv: number; // 店等級解鎖門檻
  starter: boolean; // true = 開局免費附贈、不進商店
  surface: boolean; // 可放小物（surface 寄生）：桌/櫃頂/開放層架 true；椅凳沙發卡座/其餘 false
  spriteHeightTiles: number; // 視覺高度（格）＝footprint_w × naturalH/naturalW；引擎算桌面高度用（spriteH = spriteHeightTiles × CELL）
  facings?: Facing[]; // 實際畫了哪些向；省略＝front 單向（旋轉 no-op）。back/right 加檔 <id>_back/_right.png，left 缺則引擎鏡像 right
  hostType?: 'counter-inside'; // E4：吧檯內側小家電（嵌吧檯裡、下半身被 counter_front 遮）；省略＝一般家具/小物
  frontWall?: boolean; // E10：可掛門/門旁前牆（畫在 base-fg 之上）；省略＝只能掛後牆
  counterTop?: boolean; // E11：z=furniture 但可放吧檯檯面格（加法，地板照舊可放）
  flavor: string; // 一句話 flavor 文案（docs/cafe-flavor.json 來源，查無 id 則為空字串；引擎端空字串該行不渲染）
}

